<script lang="ts">
 import {onMount,untrack} from 'svelte';import type {ToolState} from '../../types';import {importNotes,searchNotes,type Note} from './logic';import {allRecords,writeRecords} from '../../local-db';import {download} from '../../browser-files';import CopyButton from '../../components/CopyButton.svelte';
 let {state:data=$bindable()}=$props<{state:ToolState}>();untrack(()=>{data.notes??=[];data.selected??='';data.query??='';data.error??='';data.loaded??=false;});
 let status=$state(''),busy=$state(false);let selected=$derived((data.notes as Note[]).find(n=>n.id===data.selected));let filtered=$derived(searchNotes(data.notes,data.query));
 onMount(()=>{if(data.loaded)return;allRecords<Note>('notes').then(notes=>{if(notes.length>250||notes.some(n=>typeof n.id!=='string'||typeof n.title!=='string'||typeof n.body!=='string'||n.body.length>100000))throw new Error('保存済みメモの形式が無効です。');data.notes=notes;data.selected=notes[0]?.id||'';data.loaded=true;}).catch(e=>data.error=`読み込み失敗: ${e.message}`);});
 async function save(note:Note){const snapshot={...note,updated:Date.now()};note.updated=snapshot.updated;status='保存中…';try{await writeRecords('notes',[snapshot]);status='端末内に保存しました';data.error='';}catch(e){status='未保存';data.error=`保存できません。エクスポートで退避してください。${(e as Error).message}`;}}
 async function add(){if(data.notes.length>=250){data.error='最大250件です。';return;}const note={id:crypto.randomUUID(),title:'新しいメモ',body:'',updated:Date.now()};data.notes=[note,...data.notes];data.selected=note.id;await save(note);}
 async function remove(){if(!selected||!confirm('このメモを削除しますか？'))return;busy=true;try{await writeRecords('notes',[],[selected.id]);data.notes=data.notes.filter((n:Note)=>n.id!==data.selected);data.selected=data.notes[0]?.id||'';data.error='';}catch(e){data.error=(e as Error).message;}finally{busy=false;}}
 async function importFile(event:Event){const input=event.currentTarget as HTMLInputElement,file=input.files?.[0];if(!file)return;busy=true;try{if(file.size>2_000_000)throw new Error('2MB以下のJSONファイルにしてください。');const imported=importNotes(await file.text());if(data.notes.length+imported.length>250)throw new Error('合計250件を超えます。');await writeRecords('notes',imported);data.notes=[...imported,...data.notes];data.selected=imported[0]?.id||data.selected;data.error='';status='インポートしました';}catch(e){data.error=(e as Error).message;}finally{input.value='';busy=false;}}
 function exportAll(){download(new Blob([JSON.stringify({version:1,notes:data.notes},null,2)],{type:'application/json'}),'toolbox-notes.json');}
</script>
{#if data.error}<p class="error" role="alert">{data.error}</p>{/if}
{#if data.loaded}
<div class="action-row"><button class="primary" disabled={busy} onclick={add}>新規メモ</button><button onclick={exportAll}>全メモをエクスポート</button><span class="limit-note" role="status">{status}</span></div>
<label class="file-line">JSONをインポート（既存メモを残して追加）<input type="file" accept="application/json,.json" onchange={importFile} disabled={busy}/></label>
<div class="notes-layout"><section aria-label="メモ一覧"><label>メモを検索<input bind:value={data.query} maxlength="200" placeholder="タイトル・本文を検索"/></label><div class="notes-list">{#each filtered as note}<button class:selected={note.id===data.selected} onclick={()=>data.selected=note.id}><strong>{note.title||'無題'}</strong><span>{note.body.slice(0,50)||'本文なし'}</span></button>{:else}<p class="tool-note">メモがありません。</p>{/each}</div></section><section aria-label="メモ編集">{#if selected}<label>タイトル<input bind:value={selected.title} maxlength="200" oninput={e=>{selected!.title=e.currentTarget.value;save(selected!);}} disabled={busy}/></label><label>本文<textarea bind:value={selected.body} maxlength="100000" rows="16" oninput={e=>{selected!.body=e.currentTarget.value;save(selected!);}} disabled={busy}></textarea></label><div class="action-row"><CopyButton text={selected.body}/><button onclick={()=>save(selected!)}>保存を再試行</button><button disabled={busy} onclick={remove}>このメモを削除</button></div>{:else}<p class="tool-note">「新規メモ」から作成してください。</p>{/if}</section></div>
{:else}<p class="tool-note">端末内の保存領域を読み込み中。利用できない場合はブラウザ設定を確認して再読み込みしてください。</p>{/if}
<p class="tool-note">最大250件・本文各100,000文字。IndexedDBに入力ごとに自動保存します。「保存しました」を確認して閉じてください。他タブとの共同編集には非対応。バックアップはJSONで保存してください。</p>
